// OpenAI API ile iletişim kuracak servis
import axios from 'axios';

// Prompt dosyalarını import edelim
import creativePrompts from '../data/prompts/creativePrompts.json';
import moodPrompts from '../data/prompts/moodPrompts.json';
import personalPrompts from '../data/prompts/personalPrompts.json';
import careerPrompts from '../data/prompts/careerPrompts.json';

// OpenAI API için tip tanımlamaları
interface OpenAIRequestBody {
  model: string;
  messages: {
    role: string;
    content: string;
  }[];
  temperature?: number;
  max_tokens?: number;
  stream?: boolean;
}

interface OpenAIResponse {
  id: string;
  object: string;
  created: number;
  model: string;
  choices: {
    index: number;
    message: {
      role: string;
      content: string;
    };
    finish_reason: string;
  }[];
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

// Quiz cevap analizi için ara tür tanımları
interface AnswerSummary {
  answerCounts: { a: number; b: number; c: number; d: number };
  answerPattern: string;
  answerDetails: string;
  dominantTrait: string;
  secondaryTrait: string;
}

// OpenAI API için sabitleri tanımla
const BACKEND_API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001/api';
const OPENAI_MODEL = 'gpt-4o-mini';
// API anahtarı backend'e konulduğu için artık localStorage'a gerek yok

// Aura türlerini tanımla
export const auraTypes = ['yaratıcı', 'ruhsal', 'kişisel', 'kariyer'];

// Aura tipine göre prompts seçme
const getPromptsForAuraType = (auraType: string) => {
  switch (auraType) {
    case 'creative':
    case 'yaratıcı':
      return creativePrompts;
    case 'mood':
    case 'ruhsal':
      return moodPrompts;
    case 'personal':
    case 'kişisel':
      return personalPrompts;
    case 'career':
    case 'kariyer':
      return careerPrompts;
    default:
      return creativePrompts;
  }
};

// Quiz cevaplarını analiz edip özetleyen fonksiyon
export const getAnswerSummary = (answers: { [key: number]: string }): AnswerSummary => {
  // Cevapların sayılarını say
  const answerCounts = { a: 0, b: 0, c: 0, d: 0 };

  // Her cevabı değerlendir
  Object.values(answers).forEach(answer => {
    if (answer === 'a') answerCounts.a++;
    else if (answer === 'b') answerCounts.b++;
    else if (answer === 'c') answerCounts.c++;
    else if (answer === 'd') answerCounts.d++;
  });

  // En çok ve ikinci en çok verilen cevabı bul
  let dominant = 'a';
  let secondary = 'a';
  let maxCount = answerCounts.a;
  let secondMaxCount = -1;

  // En çok verilen cevabı bul
  for (const [answer, count] of Object.entries(answerCounts)) {
    if (count > maxCount) {
      secondary = dominant;
      secondMaxCount = maxCount;
      dominant = answer;
      maxCount = count;
    } else if (count > secondMaxCount && answer !== dominant) {
      secondary = answer;
      secondMaxCount = count;
    }
  }

  // Cevapların desenini oluştur (örn: "3a2b1c2d")
  const answerPattern = `${answerCounts.a}a${answerCounts.b}b${answerCounts.c}c${answerCounts.d}d`;

  // Dominant ve secondary özelliklere göre kişilik özelliklerini belirle
  let dominantTrait = '';
  let secondaryTrait = '';

  switch (dominant) {
    case 'a':
      dominantTrait = 'analitik';
      break;
    case 'b':
      dominantTrait = 'yaratıcı';
      break;
    case 'c':
      dominantTrait = 'empatik';
      break;
    case 'd':
      dominantTrait = 'enerjik';
      break;
  }

  switch (secondary) {
    case 'a':
      secondaryTrait = 'analitik';
      break;
    case 'b':
      secondaryTrait = 'yaratıcı';
      break;
    case 'c':
      secondaryTrait = 'empatik';
      break;
    case 'd':
      secondaryTrait = 'enerjik';
      break;
  }

  // Cevap detaylarını okunabilir metin olarak hazırla
  const answerDetails = Object.entries(answers)
    .map(([questionNumber, answer]) => {
      return `Soru ${questionNumber}: ${answer}`;
    })
    .join('\n');

  return {
    answerCounts,
    answerPattern,
    answerDetails,
    dominantTrait,
    secondaryTrait
  };
};

// OpenAI için mesajları hazırlama
const prepareMessagesForOpenAI = (auraType: string, username: string, answers: any): any[] => {
  // Cevapların detaylı analizini yap
  const answerSummary = getAnswerSummary(answers || {});
  
  // Aura tipine göre promptları al
  const prompts = getPromptsForAuraType(auraType);
  const systemPrompt = prompts.systemPrompt;
  
  // Kullanıcı mesajı oluşturma
  const userMessage = `
Merhaba, ben ${username || 'bir kullanıcı'}. 
Aşağıdaki quiz cevaplarıma göre benim için bir ${auraType} Aura hikayesi yazar mısın?

Quiz Cevaplarım:
${answerSummary.answerDetails}

Cevaplarıma göre baskın özelliğim "${answerSummary.dominantTrait}", ikincil özelliğim "${answerSummary.secondaryTrait}".

Lütfen benim için türkçe olarak, içten, derin, anlamlı ve kişiselleştirilmiş bir aura hikayesi yaz. 
Hikaye ruhsal bir yolculuğu ifade etmeli ancak gerçekçi ve uygulanabilir içgörüler de sunmalı.
Sürreal ya da çok soyut bir hikayeden ziyade hayatıma uygulanabilecek gerçekçi içgörüler içeren bir hikaye olsun.
Hikaye en az 4-6 paragraf uzunluğunda, detaylı ve kapsamlı olmalı.
Her bölümü derinlemesine ele al, özellikle "Aura Hikayen" kısmı çok önemli.
Tamamen benim cevaplarıma göre kişiselleştirilmiş ve içgörü dolu bir hikaye hazırla.
`;
  
  // Mesajları oluştur
  return [
    { role: "system", content: systemPrompt },
    { role: "user", content: userMessage }
  ];
};

// Hikaye alma fonksiyonu
export const getAuraStoryFromOpenAI = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string }
): Promise<string> => {
  try {
    // Mesajları hazırla
    const messages = prepareMessagesForOpenAI(auraType, username, answers);
    
    // Backend API'sine istek gönder
    const response = await axios.post(
      `${BACKEND_API_URL}/aura/story`,
      {
        auraType,
        username,
        answers,
        messages
      }
    );
    
    // Cevabı döndür
    return response.data.story;
  } catch (error) {
    console.error('OpenAI API hatası:', error);
    return "Aura hikayeniz şu anda oluşturulamıyor. Lütfen daha sonra tekrar deneyin.";
  }
};

// İçgörüler için mesajları hazırlama
const prepareInsightsMessagesForOpenAI = (auraType: string, username: string, answers: any, detailedAnswers?: any): any[] => {
  // Aura tipine göre promptları al
  const prompts = getPromptsForAuraType(auraType);
  const systemPrompt = prompts.insightsPrompt;
  
  // Cevapları özetle
  const summary = getAnswerSummary(answers);
  
  // Detaylı cevapları kullanarak daha zengin bir sorgu oluştur
  let answerDetailsText = summary.answerDetails;
  if (detailedAnswers && Array.isArray(detailedAnswers) && detailedAnswers.length > 0) {
    answerDetailsText = detailedAnswers.map((answer: any) => 
      `Soru: ${answer.question}\nCevap: ${answer.answerText}`
    ).join('\n\n');
  }
  
  return [
    {
      role: "system",
      content: systemPrompt
    },
    {
      role: "user",
      content: `Merhaba, ben ${username}. Test sonuçlarıma göre içgörüleri hazırlar mısın?\n\n${answerDetailsText}`
    }
  ];
};

// İçgörüler alma fonksiyonu
export const getAuraInsightsFromOpenAI = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string },
  detailedAnswers?: any
): Promise<{
  strengths: string,
  potential: string,
  thinkingStyle: string,
  auraTitle: string,
  source: 'openai' | 'default'
}> => {
  try {
    // İçgörü promptunu hazırla
    const messages = prepareInsightsMessagesForOpenAI(auraType, username, answers, detailedAnswers);
    
    // Backend API'sine istek gönder
    const response = await axios.post(
      `${BACKEND_API_URL}/aura/insights`,
      {
        auraType,
        username,
        answers,
        detailedAnswers,
        messages
      }
    );
    
    return {
      ...response.data,
      source: 'openai'
    };
  } catch (error) {
    console.error('OpenAI API hatası (içgörüler):', error);
    
    // Hata durumunda varsayılan değerler döndür
    return {
      strengths: "Güçlü yönleriniz şu anda yüklenemiyor.",
      potential: "Potansiyeliniz şu anda yüklenemiyor.",
      thinkingStyle: "Düşünme stiliniz şu anda yüklenemiyor.",
      auraTitle: `${auraType.charAt(0).toUpperCase() + auraType.slice(1)} Aura`,
      source: 'default'
    };
  }
};

// Birleştirilmiş aura verisi için mesajları hazırlama
const prepareCombinedMessagesForOpenAI = (auraType: string, username: string, answers: any): any[] => {
  const prompts = getPromptsForAuraType(auraType);
  const combinedPrompt = prompts.combinedPrompt;
  const summary = getAnswerSummary(answers);
  
  return [
    {
      role: "system",
      content: combinedPrompt + `\n\n-----\n\nKişi hakkında bilgiler:\nAd: ${username}\nAura Tipi: ${auraType}\nQuiz Cevapları: ${summary.answerDetails}\nBaskın Özellik: ${summary.dominantTrait}\nİkincil Özellik: ${summary.secondaryTrait}\n\n-----\n\nÖNEMLİ: \n- Yanıtını TAM OLARAK bu formatta ver\n- Formatı kesinlikle değiştirme\n- Tüm BAŞLIKLAR ve NUMARALANDIRMALAR bu şekilde kalmalı\n- Her bölüm için YETERLİ ve DETAYLI bilgi ver\n- Türkçe yanıt ver\n- Her bölümü MUTLAKA doldur ve hiçbir bölümü boş bırakma`
    }
  ];
};

// Birleştirilmiş veri alma fonksiyonu
export const getCombinedAuraDataFromOpenAI = async (
  auraType: string,
  username: string,
  answers: { [key: number]: string }
): Promise<{
  story: string,
  strengths: string,
  potential: string,
  thinkingStyle: string,
  auraTitle: string,
  source: 'openai' | 'default'
}> => {
  try {
    console.log("[OpenAI] Backend API'sine istek gönderiliyor");
    
    // Backend API'sine istek gönder
    const response = await axios.post(
      `${BACKEND_API_URL}/aura/combined`,
      {
        auraType,
        username,
        answers
      }
    );
    
    console.log("[OpenAI] Backend yanıt aldı:", response.data.source);
    
    return {
      ...response.data,
      source: response.data.source || 'openai'
    };
  } catch (error) {
    console.error('OpenAI API hatası (birleştirilmiş):', error);
    
    // Hata durumunda varsayılan değerler döndür
    return {
      story: "Aura hikayeniz şu anda yüklenemiyor.",
      strengths: "Güçlü yönleriniz şu anda yüklenemiyor.",
      potential: "Potansiyeliniz şu anda yüklenemiyor.",
      thinkingStyle: "Düşünme stiliniz şu anda yüklenemiyor.",
      auraTitle: `${auraType.charAt(0).toUpperCase() + auraType.slice(1)} Aura`,
      source: 'default'
    };
  }
};

// Dinamik Aura tipini belirleme (cevaplara göre)
export const determineDynamicAuraType = (answers: { [key: number]: string }): string => {
  // getAnswerSummary fonksiyonuyla hesaplanır
  const summary = getAnswerSummary(answers);
  return summary.dominantTrait;
};
